"use strict";

// The package's whole callable API is chosen AT RUNTIME by a resolvable
// LOCAL CALL whose own body always throws -- but, unlike RWF-016 through
// RWF-024's fixtures, the call sits in NO privileged syntactic slot at
// all. It is an ordinary call ARGUMENT:
//
//     sink(before(), bail(), after());
//
// ECMAScript's EvaluateCall builds the argument list, left to right,
// BEFORE the callee is entered. So `before()` runs, `bail()` throws,
// `after()` never runs, `sink` is never called, and module evaluation on
// this branch ends there. Nothing about `sink` needs to be known for that
// to hold -- which is the point: this is a property of ARGUMENT
// evaluation, not of the function being called. See
// fixtures/commonjs-circular-import-expression-position-throw-ground-truth/
// for a real node-executed proof.
const danger = require("./danger");

// The branch that reaches the vulnerable sink. Nothing in this file calls
// it: the ONLY way it ever runs is by being the module's exported value.
function dangerousOp(input) {
  return danger.explode(input);
}

// The branch that does not.
function safeOp(input) {
  return "safe:" + input;
}

// A resolvable local callable whose entire body is a single unconditional
// throw -- definitely abrupt by RWF-016's own model, unchanged.
function bail() {
  throw new Error("fast mode is not supported here");
}

// Harmless local callables, so that argument evaluation ORDER is
// exercised rather than assumed.
function before() {
  return "before";
}

function after() {
  return "after";
}

function sink(a, b, c) {
  return [a, b, c];
}

if (process.env.FIXTURE_LIB_MODE === "fast") {
  module.exports = dangerousOp;
  // Arguments evaluate in source order as part of evaluating the call, so
  // `before()` evaluates and then this necessarily invokes `bail()`. It
  // never returns, `after()` is never evaluated, `sink` is never entered,
  // and module evaluation on this branch ends here.
  sink(before(), bail(), after());
}

module.exports = safeOp;
